import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/Books/02-SupplementaryArticles/Thinking/02-Are-war-robots-reliable.html","title":"02-战争机器人靠谱吗？","lang":"zh-CN","frontmatter":{"title":"02-战争机器人靠谱吗？","icon":"read","date":"2025-04-25T18:58:02.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":false,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"watermark":{"width":200,"height":200,"content":"《编程启蒙：思维与代码》作者：黄家宝","opacity":0.5},"description":"1. 谁来按下“开火”键？AI 战场的两难选择 来，先来玩个“假如你是指挥官”的小测试： 有个危险分子从监狱逃脱，藏身于一座居民楼中。你得把他抓住，但里面还有无辜居民，不能误伤！你手上有最先进的人工智能技术可以调动——你打算怎么做？ 停一停，先别急着回答，想一想：怎么做，才能又快又准又安全？ 要是我来选，我可能不会直接派士兵冲进去，太危险了。我会考虑这...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"02-战争机器人靠谱吗？\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2025-04-25T18:58:02.000Z\\",\\"dateModified\\":\\"2025-05-07T11:44:53.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/Books/02-SupplementaryArticles/Thinking/02-Are-war-robots-reliable.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"02-战争机器人靠谱吗？"}],["meta",{"property":"og:description","content":"1. 谁来按下“开火”键？AI 战场的两难选择 来，先来玩个“假如你是指挥官”的小测试： 有个危险分子从监狱逃脱，藏身于一座居民楼中。你得把他抓住，但里面还有无辜居民，不能误伤！你手上有最先进的人工智能技术可以调动——你打算怎么做？ 停一停，先别急着回答，想一想：怎么做，才能又快又准又安全？ 要是我来选，我可能不会直接派士兵冲进去，太危险了。我会考虑这..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-05-07T11:44:53.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2025-04-25T18:58:02.000Z"}],["meta",{"property":"article:modified_time","content":"2025-05-07T11:44:53.000Z"}]]},"git":{"createdTime":1669634625000,"updatedTime":1746618293000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":13,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"74434ca22b4dbb049c5d8cf6d6a63a10b07fd700","time":1746618293000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"feat: 更新侧边栏，添加目录项并禁用各章节的导航栏"},{"hash":"9c9b2ba2b8ef4cc1b61c10448101aa350e9450ee","time":1746617928000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"feat: 更新思维章节，添加水印信息并调整侧边栏内容"},{"hash":"9fe778ec384b68cfc405b291cf05475dbfed5c84","time":1746616663000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新"},{"hash":"32742c5a7b4409f9d8343e4a7f4a392536d11f6a","time":1746616274000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新思维补充文章"},{"hash":"3a296fb1bb050a6931bed646dee087ff73500518","time":1745591514000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"9ce3f18bd55b4496f61dc288cbe02cee98e4712d","time":1745590866000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add initial draft of \\"How did hackers steal your lucky money\\" article"},{"hash":"fe896e6c18a95af350fa6134c22f57662b89af46","time":1745581900000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文章内容，增加对人工智能在战场应用的讨论及其潜在风险分析"},{"hash":"aa01ecbf186ea5a5667b2605e6da98f6ab3b82cb","time":1745579315000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"4d098f34b968c7f9162e7d143141d46669c76d6e","time":1745325668000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add articles on programming and cooking: \\"Can computer programs really kill people?\\" and \\"清蒸鲈鱼\\""},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":6.21,"words":1863},"filePathRelative":"Books/02-SupplementaryArticles/Thinking/02-Are-war-robots-reliable.md","excerpt":"<h2>1. 谁来按下“开火”键？AI 战场的两难选择</h2>\\n<p>来，先来玩个“假如你是指挥官”的小测试：</p>\\n<p>有个危险分子从监狱逃脱，藏身于一座居民楼中。你得把他抓住，但里面还有无辜居民，不能误伤！你手上有最先进的人工智能技术可以调动——你打算怎么做？</p>\\n<p>停一停，先别急着回答，想一想：怎么做，才能又快又准又安全？</p>\\n<p>要是我来选，我可能不会直接派士兵冲进去，太危险了。我会考虑这样一个组合拳：</p>\\n<ul>\\n<li>第一步：派出<strong>无人机</strong>先侦查现场。</li>\\n<li>第二步：让无人机搭载“<strong>人脸识别系统</strong>”，识别谁是平民，谁是逃犯。</li>\\n<li>第三步：识别成功后，无人机用“非致命武器”将目标制服，比如电击枪。</li>\\n<li>最后：等目标昏迷，再派士兵上门“请”他喝茶。</li>\\n</ul>","autoDesc":true}`),a={name:`02-Are-war-robots-reliable.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="_1-谁来按下-开火-键-ai-战场的两难选择" tabindex="-1"><a class="header-anchor" href="#_1-谁来按下-开火-键-ai-战场的两难选择"><span>1. 谁来按下“开火”键？AI 战场的两难选择</span></a></h2><p>来，先来玩个“假如你是指挥官”的小测试：</p><p>有个危险分子从监狱逃脱，藏身于一座居民楼中。你得把他抓住，但里面还有无辜居民，不能误伤！你手上有最先进的人工智能技术可以调动——你打算怎么做？</p><p>停一停，先别急着回答，想一想：怎么做，才能又快又准又安全？</p><p>要是我来选，我可能不会直接派士兵冲进去，太危险了。我会考虑这样一个组合拳：</p><ul><li>第一步：派出<strong>无人机</strong>先侦查现场。</li><li>第二步：让无人机搭载“<strong>人脸识别系统</strong>”，识别谁是平民，谁是逃犯。</li><li>第三步：识别成功后，无人机用“非致命武器”将目标制服，比如电击枪。</li><li>最后：等目标昏迷，再派士兵上门“请”他喝茶。</li></ul><p>听起来是不是很高科技？就像电影一样炫酷？其实，这种做法在军事领域已经不是幻想。</p><p>你想的方法可能和我想的不一样，但你会发现，有了<strong>人工智能技术</strong>的帮助，想抓住坏人简直是轻而易举。你现在是不是觉得，这人工智能技术太方便了，能消灭坏人，又不会误伤好人，要是真把这项技术用在战场上，说不定能减少很多无辜的伤亡呢。你还别说，真的有！</p><h2 id="_2-这不是宠物狗-是-战争载具" tabindex="-1"><a class="header-anchor" href="#_2-这不是宠物狗-是-战争载具"><span>2. 这不是宠物狗，是“战争载具”</span></a></h2><figure><img src="/assets/image-20250425214432566-C68A6cBA.png" alt="BigDog" tabindex="0" loading="lazy"><figcaption>BigDog</figcaption></figure><p>在 2010年美国在阿富汗部署的一种新型机器人，它的名字叫“BigDog”（中文可以叫“大狗”机器人）——由<strong>波士顿动力</strong>公司研发。</p><p>别被它的名字骗了，它可不是用来陪士兵散步的。这家伙四条腿像狗一样行走，爬山涉水毫不费力，而且就算你踢它一脚，它也能很快重新站稳，堪称“铁皮四足野兽”。</p><p>为什么美军要带着“大狗”上战场？原因很简单：<strong>装备运输</strong>难题。</p><figure><img src="/assets/image-20250425215254311-CtDUVFMP.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>一般情况下，军队是靠汽车来运送装备。但是阿富汗地形崎岖，车子开不了，最早他们是用<strong>骡子</strong>运装备。于是就有了这样一幕：高科技士兵一手拿步枪，一手牵着骡子……酷不起来。</p><figure><img src="/assets/image-20250425215057274-B8wppicg.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>酷不酷倒不是最主要的，主要是：万一有敌人发起突袭，枪声一响，骡子可能被吓得四处乱跑，士兵们打完仗还要漫山遍野去找骡子，想想这个画面也是很搞笑。</p><p>于是，美国国防部就拍板开发机器骡子。最终，大狗机器人诞生了——它能驮着<strong>几百斤</strong>的物资，自动跟随士兵行动。这样遇到突袭的时候，不会出现骡子那般乱跑，甚至走丢了士兵还可以通过遥控回到基地。</p><p>但问题也随之而来：它太吵了。不是“汪汪”叫，而是发<strong>动机声音大得惊人</strong>，几百米外都能听到，完全无法偷偷行动。而且它结构复杂，士兵修不好，一出毛病就只能干瞪眼。</p><p>最后美军还是又用回了骡子，哈哈哈哈哈……好笑不。</p><figure><img src="/assets/image-20250425215505546-C2BMxEcc.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>不过大狗也没完全退役——它被一些国家改造成了“带枪的战士”。</p><p>注意：虽然大狗被我们改装，也让大狗装着武器，但最终决定开枪的是遥控器那头的<strong>人类</strong>。</p><h2 id="_3-谁来做决定-ai-还是人类" tabindex="-1"><a class="header-anchor" href="#_3-谁来做决定-ai-还是人类"><span>3. 谁来做决定，AI 还是人类？</span></a></h2><figure><img src="/assets/image-20250425215918482-D474wgi1.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你可能会想，既然大狗能扛枪，那是不是能装上“<strong>识别人脸自动射击</strong>”的系统？</p><p>想象一下：机器人冲上战场，自动判断敌我，开枪射击，战斗结束时，人类还在后方喝咖啡。</p><p>听起来很高效，对吧？</p><p>在这个想法上，科学家却不这么看，因为这样太危险了！</p><figure><img src="/assets/image-20250425220211602-DYgfNjuP.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>2017年，有人做了一个警示视频：恐怖分子掌握了<strong>AI技术</strong>，给无人机上面装了人脸识别功能。无人机用 AI 识别目标，然后自动引爆炸弹——一旦识别出“人脸”，就发动攻击。哪怕你戴口罩遮半张脸，也逃不过它的识别系统。</p><p>虽然那段视频是假的，但它背后的技术是真实存在的。科学家们并不是在拍恐怖片，而是在提醒我们：如果这项技术被恐怖分子掌握，后果不堪设想。</p><p>如果 AI“认错人”，会不会误伤平民？如果程序被<strong>黑客控制</strong>，它是不是就可能“倒戈”攻击好人？这不是科幻，这是现实可能发生的事。</p><figure><img src="/assets/image-20250425220639640-CuAejje0.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>于是，2017年，包括<strong>斯蒂芬·霍金</strong>和<strong>埃隆·马斯克</strong>在内的全球顶级科学家，联名发出呼吁：反对 AI武器的开发。</p><figure><img src="/assets/image-20250425221429694-CoeVCrOf.png" alt="联合声明图片·AI生成图片，内容切勿全信" tabindex="0" loading="lazy"><figcaption>联合声明图片·AI生成图片，内容切勿全信</figcaption></figure><h2 id="_4-是福是祸-关键看-怎么用" tabindex="-1"><a class="header-anchor" href="#_4-是福是祸-关键看-怎么用"><span>4. 是福是祸？关键看“怎么用”</span></a></h2><figure><img src="/assets/image-20250425222614030-CRIwBzHB.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>人工智能到底是救世主还是潘多拉魔盒？</p><p>在回答这个问题之前，我要教你一个思考问题的方法叫：<strong>做辩证思维</strong>。在生活中，我们特别喜欢说一件事好或者不好。</p><p>但其实很多事情都有<strong>两面性</strong>，就是既有好的一面也有坏的一面，我们做判断的时候，不能太过绝对。</p><p>所以，上面问题的答案不是“选项A”或“选项B”，而是：<strong>看你怎么用它</strong>。</p><p>如果你给机器人装上医疗箱，它可以在地震废墟中搜救生命。如果你给它装上武器，那它就是战场上的杀戮机器。</p><p>再次强调：我们需要学会<strong>辩证思维</strong>这种重要的思维方式——不是非黑即白，不是一好一坏，而是承认“技术有两面性”。当我们评价一项技术时，不只是看它能干什么，还要看我们愿意用它来做什么。</p><p>并且用辩证的思维去看问题，你就会比别人看得<strong>更全面</strong>。这种思考方式，你以后在历史课上也会经常用到。在分析一个历史事件的时候，不要简单地说好或者不好，试试能不能从不同的角度去分析它，得出更加可靠的结论。</p><p>切记：<strong>技术本身不违法，主要看使用技术的人！</strong></p><p>最后，我们说回人工智能技术：现在科学家们提倡要加快研究人工智能技术，并不是因为他们没有看到人工智能技术的问题。他们用<strong>辩证思维</strong>分析之后，认为人工智能给人类带来的<strong>好处是多于坏处</strong>的。而且，我们也有足够的时间来解决<strong>人工智能滥用</strong>这件事。所以，现在应当继续发展人工智能技术。</p>`,47)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};